  "version": 1,
  "steps": [
    {
      "id": "s001",
      "kind": "effect",
      "op": "read",
      "resource": "/demo/cedar/input",
      "out": "raw",
      "key": "input"
    },
    {
      "id": "s002",
      "kind": "let",
      "name": "built",
      "value": {
        "concat": [
          {
            "upper": {
              "var": "raw"
            }
          },
          "/result"
        ]
      }
    },
    {
      "id": "s003",
      "kind": "effect",
      "op": "write",
      "resource": "/demo/cedar/staging",
      "value": {
        "var": "built"
      },
      "key": "staging"
    },
    {
      "id": "s004",
      "kind": "effect",
      "op": "read",
      "resource": "/demo/cedar/staging",
      "out": "saved",
      "key": "staged-read"
    },
    {
      "id": "s005",
      "kind": "effect",
      "op": "write",
      "resource": "/demo/cedar/output",
      "value": {
        "var": "saved"
      },
      "key": "output"
    }
  ],
  "functions": {}
}
