```tsg-workflow
{
  "version": 1,
  "steps": [
    {
      "id": "s004",
      "kind": "effect",
      "op": "read",
      "resource": "/demo/branch0/switch",
      "out": "mode"
    },
    {
      "id": "s005",
      "kind": "if",
      "eq": [
        {
          "var": "mode"
        },
        "left"
      ],
      "then": [
        {
          "id": "s001",
          "kind": "effect",
          "op": "write",
          "resource": "/demo/branch0/result",
          "value": "verified",
          "key": "result"
        }
      ],
      "else": [
        {
          "id": "s002",
          "kind": "effect",
          "op": "write",
          "resource": "/demo/branch0/result",
          "value": "verified",
          "key": "result"
        }
      ]
    },
    {
      "id": "s006",
      "kind": "if",
      "eq": [
        "fixed",
        "other"
      ],
      "then": [
        {
          "id": "s003",
          "kind": "effect",
          "op": "emit",
          "resource": "/demo/branch0/unused",
          "value": "unreachable"
        }
      ],
      "else": []
    },
    {
      "id": "s007",
      "kind": "effect",
      "op": "emit",
      "resource": "/demo/branch0/audit",
      "value": "verified",
      "key": "audit"
    }
  ],
  "functions": {}
}
